head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gIsurCd;
scwin.kosDepOk;
scwin.fr_SecuGrpId = SECUGRP_ID_ST;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_list_sync = function() {
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var url = "/listingCommon.do?SCREN_ID=ULDSTF20507.gfm&SCREN_PROCES_TP_CD=01&method=listGeneralForDynamic" + "&outputMessageId=REALINVSTG_TOTALFIRST_LIST" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&param01=" + vMarketTpCd;
    if (MxTab_1.getSelectedTabIndex() == 1) {
        url += "&queryId=lds.stf.lstsrch.select.total.realinvstg.search";
        dts_List.DataID = encodeURI(url);
        dts_List.reset();
        //ShowWin(grd_Grid);

    } else {
        url += "&queryId=lds.stf.lstsrch.select.total2.realinvstg.search";
        dts_List2.DataID = encodeURI(url);
        dts_List2.reset();
        //ShowWin(grd_Grid2);			

    }
    scwin.setHeader();
};
scwin.setHeader = function() {
    var nowDate = $c.ut.fn_get_nowDate(dts_Date);
    var year = nowDate.substring(0, 4);
    var month = nowDate.substring(4, 6);
    var day = nowDate.substring(6, 8);
    var dNow = new Date(parseInt(year), month - 1, parseInt(day));
    var targetGrid;
    if (MxTab_1.getSelectedTabIndex() == 1) {
        targetGrid = grd_Grid;
        var month = dNow.getMonth() + 1;
        if ((month + "").length == 1) month = "0" + month;
        targetGrid.setColumnProp("CNT11", "Name", dNow.getYear() + "-" + month + "-" + dNow.getDate());
    } else {
        targetGrid = grd_Grid2;
        dNow.setMonth(dNow.getMonth() - 1);
        targetGrid.setColumnProp("CNT11", "Name", dNow.getYear() + "." + (parseInt(dNow.getMonth()) + 1));
    }
    var nowYear = dNow.getYear();
    targetGrid.setColumnProp("CNT1", "Name", nowYear - 10);
    targetGrid.setColumnProp("CNT2", "Name", nowYear - 9);
    targetGrid.setColumnProp("CNT3", "Name", nowYear - 8);
    targetGrid.setColumnProp("CNT4", "Name", nowYear - 7);
    targetGrid.setColumnProp("CNT5", "Name", nowYear - 6);
    targetGrid.setColumnProp("CNT6", "Name", nowYear - 5);
    targetGrid.setColumnProp("CNT7", "Name", nowYear - 4);
    targetGrid.setColumnProp("CNT8", "Name", nowYear - 3);
    targetGrid.setColumnProp("CNT9", "Name", nowYear - 2);
    targetGrid.setColumnProp("CNT10", "Name", nowYear - 1);
};
scwin.setSum = function() {
    var nextValue = 0;
    for (var i = 1, j = 12; i < j; i++) {
        var columnName = "CNT" + i;
        //신규 계
        var totalValue = dts_List2.getCellData(18, columnName);
        //19 - 전기이월
        var preValue = 0;
        if (i == 1) {
            preValue = dts_List2.getCellData(19, columnName);
        } else {
            preValue = nextValue;
            dts_List2.setCellData(19, columnName, nextValue);
        }
        var aTotalValue = Number(totalValue) + Number(preValue);
        if (aTotalValue != 0) {
            dts_List2.setCellData(20, columnName, aTotalValue);
        }
        //계(b)

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        var closeTotal = Number(dts_List2.getCellData(21, columnName)) + Number(dts_List2.getCellData(22, columnName)) + Number(dts_List2.getCellData(23, columnName)) + Number(dts_List2.getCellData(24, columnName));
        dts_List2.setCellData(25, columnName, /*ORG SRC: dts_List2.setNameString(25, columnName, dts_List2.NameString(25, columnName) = );*/ X = X);
        var nonClose = aTotalValue - Number(closeTotal);
        nextValue = nonClose;
        if (nonClose != 0) {
            dts_List2.setCellData(27, columnName, nonClose);
        }
    }
};
scwin.checkKosdaq = function() {
    if (js_market == "2" && scwin.kosDepOk != "OK") {
        $c.win.alert("위원회 심의현황 조회권한이 없습니다.");
        return false;
    } else {
        return true;
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave("ULDSTF20507.gfm", SCREN_PROCS_TP_CD_07);
    if (MxTab_1.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_Grid, "위원회 심의현황", "", "8");
    } else {
        $c.data.downloadGridViewExcel(grd_Grid2, "실질심사 운용현황", "", "8");
    }
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    //CloseWin(rowcount, grd_Grid); 

};
scwin.gform_onload = function() {
    if (js_market == "1" || js_market == "2") {
        //showObj(panel_mkt_gubun, false);
        $c.stf.setObjectValue(rdo_MARKET_TP_CD, js_market);
        rdo_MARKET_TP_CD.setDisabled(true);
    }
    if (js_market == "2") {
        //코스닥인경우 위원회 심의현황 탭은 기업심사3팀만 조회가능
        if (js_dep_cd == '3H20') {
            scwin.kosDepOk = "OK";
            MxTab_1.setSelectedTabIndex(1);
        } else {
            scwin.kosDepOk = "NO";
            MxTab_1.setSelectedTabIndex(2);
            //탭을 안보이게 하기위해서 
            MxTab_1.Format = '' + '<tabpage title="실질심사 운용현황" divid="panel_2"></tabpage>';
        }
    } else {
        MxTab_1.setSelectedTabIndex(1);
    }
    scwin.fn_list_sync();
};
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    scwin.setSum();
    //CloseWin(rowcount, grd_Grid2); 

};
scwin.dts_List2_OnLoadError = function() {
    $c.stf.alert_error(dts_List2);
};
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.MxTab_1_CanSelChange = function(nIndex) {
    //return checkKosdaq();

};
